class MonitorV519UiTests {
 static int checks,failures;static object Get(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,args);}
 static void Check(bool ok,string name){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+name);}
 static T Find<T>(DependencyObject o,Func<T,bool> test)where T:DependencyObject{var item=o as T;if(item!=null&&test(item))return item;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++){var child=Find<T>(VisualTreeHelper.GetChild(o,i),test);if(child!=null)return child;}return null;}
 static T Named<T>(DependencyObject o,string name)where T:DependencyObject{return Find<T>(o,x=>System.Windows.Automation.AutomationProperties.GetName(x)==name);}
 static void Pump(int ms=100){var f=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();f.Continue=false;};timer.Start();Dispatcher.PushFrame(f);}
 static void Click(Window w,string text){var b=Find<Button>(w,x=>Convert.ToString(x.Content)==text);if(b==null)throw new Exception("Missing button "+text);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(b));using(var stream=File.Create(path))encoder.Save(stream);}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump(500);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();var warmUntil=DateTime.UtcNow.AddSeconds(15);while(Get(pet,"assistantSnapshot")==null&&DateTime.UtcNow<warmUntil)Pump(100);var timestamps=new List<DateTime>();for(int i=0;i<12;i++){Pump(500);var snapshot=(AssistantSnapshot)Get(pet,"assistantSnapshot");if(snapshot!=null&&snapshot.Sample!=null&&!timestamps.Contains(snapshot.Sample.Utc))timestamps.Add(snapshot.Sample.Utc);}var gaps=timestamps.Skip(1).Select((t,i)=>(t-timestamps[i]).TotalMilliseconds).ToArray();Console.WriteLine("CADENCE samples="+timestamps.Count+" gaps="+String.Join(",",gaps.Select(x=>x.ToString("F0")))+" notices="+String.Join(";",assistant.Notices.Items.Where(x=>x.Contains("刷新失败"))));Check(timestamps.Count>=5,"real running pet publishes at least five samples in six seconds");Check(gaps.Length>0&&gaps.Average()<1400&&gaps.Max()<2200,"actual default cadence approximately one second");
 Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("监控与预警");Pump();var interval=Named<ComboBox>(w,"实时采样间隔");Check(interval!=null&&interval.Items.Count==4,"sampling interval selectable");interval.SelectedIndex=0;Check(assistant.Config.Monitor.RefreshMilliseconds==500,"half second option applied");Click(w,"下载限速");Check(Find<Button>(w,b=>Convert.ToString(b.Content)=="启用整机下载限速（管理员授权）")!=null,"explicit start and administrator warning visible");Check(!assistant.Limiter.Running,"limiter disabled by default and not started by opening settings");Shot(w,Path.Combine(args[0],"download-limit-native.png"));Click(w,"Codex额度");Named<TextBox>(w,"五小时剩余预警（%）").Text="27";Named<Slider>(w,"周剩余预警（%）滑块").Value=16;Click(w,"保存额度预警");Check(assistant.Config.Monitor.Quota.FiveHourThreshold==27&&assistant.Config.Monitor.Quota.WeeklyThreshold==16,"both quota thresholds saved from text and slider");Shot(w,Path.Combine(args[0],"quota-settings-native.png"));Click(w,"将两项额度加入任务栏");Click(w,"间距与留白");var slider=Named<Slider>(w,"列与列间隔（0–120）滑块");slider.Value=36;var draft=(MonitorConfig)Get(w,"taskbarDraft");Check(draft.Appearance.ItemGap==36,"column gap slider updates preview draft");Shot(w,Path.Combine(args[0],"spacing-native.png"));Click(w,"布局与屏幕");Click(w,"一键双行均匀排列");Check(draft.Appearance.EqualColumns&&draft.Appearance.Rows==2&&!draft.Appearance.AutoRows,"even two row button updates visible settings");Shot(w,Path.Combine(args[0],"layout-native.png"));Click(w,"字体与颜色");var custom=Named<TextBox>(w,"默认数值颜色");custom.Text="#7BCFE5";Check(!Find<CheckBox>(w,x=>Convert.ToString(x.Content)=="文字自动适应Windows深浅色").IsChecked.Value,"picking custom text color exits automatic theme");Check(draft.Appearance.ValueColor=="#7BCFE5"&&!draft.Appearance.AutoTheme,"custom color applied to preview");Click(w,"应用并保存任务栏外观");var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(restored.Config.Monitor.Appearance.ItemGap==36&&restored.Config.Monitor.Appearance.EqualColumns&&restored.Config.Monitor.TaskbarItems.Contains("codex7d"),"spacing layout and quota selections persist");restored.Telemetry.Dispose();Shot(w,Path.Combine(args[0],"colors-native.png"));w.ShowPage("监控与预警");Pump();Click(w,"数据来源");Named<ComboBox>(w,"出口查询通道").SelectedIndex=2;Named<TextBox>(w,"HTTP代理地址").Text="http://127.0.0.1:7890";Click(w,"保存出口连接方式");Check(assistant.Config.Monitor.ExitProxyMode=="manual","manual exit connection saved");Shot(w,Path.Combine(args[0],"exit-settings-native.png"));
 var card=new MonitorCard(new MonitorConfig(),null){Owner=pet};card.Show();var now=DateTime.UtcNow;card.Update(new SystemSample{Utc=now,Cpu=42,Gpu=36,MemoryUsed=8,MemoryTotal=16,DiskBusy=14,Quota=new CodexQuotaSnapshot{CheckedUtc=now,State="界面示例（不是实际额度）",Windows=new List<CodexQuotaWindow>{new CodexQuotaWindow{Minutes=300,Remaining=68,ResetUtc=now.AddHours(3)},new CodexQuotaWindow{Minutes=10080,Remaining=42,ResetUtc=now.AddDays(2)}}}});Shot(card,Path.Combine(args[0],"details-native.png"));card.Close();
 }catch(Exception e){failures++;Console.WriteLine(e);}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"v519-ui-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");return failures==0?0:1;}
